// Standalone wiring diagnostic: disconnect the driver and remove actuator power.
// Selected only by the gpio17-probe environment; no arm control or calibration runs.
#include "board_config.h"
#include "serial_transport.h"

#include "driver/gpio.h"
#include "driver/ledc.h"
#include "esp_err.h"
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"

extern "C" void app_main() {
  const actuators::Config board = actuators::boardConfig();

  // Latch safe levels before enabling outputs. EN also needs its external pull-up
  // during reset. No servo pulses or STEP edges are generated by this firmware.
  ESP_ERROR_CHECK(gpio_set_level(static_cast<gpio_num_t>(board.pins.enable), 1));
  uint64_t disabledPins = 1ULL << board.pins.enable;
  for (int32_t pin : board.pins.servo) {
    ESP_ERROR_CHECK(gpio_set_level(static_cast<gpio_num_t>(pin), 0));
    disabledPins |= 1ULL << pin;
  }
  ESP_ERROR_CHECK(gpio_set_level(static_cast<gpio_num_t>(board.pins.step), 0));
  ESP_ERROR_CHECK(gpio_set_level(static_cast<gpio_num_t>(board.pins.direction), 0));
  disabledPins |= (1ULL << board.pins.step) | (1ULL << board.pins.direction);
  gpio_config_t outputs{};
  outputs.pin_bit_mask = disabledPins;
  outputs.mode = GPIO_MODE_OUTPUT;
  ESP_ERROR_CHECK(gpio_config(&outputs));

  ledc_timer_config_t timer{};
  timer.speed_mode = LEDC_LOW_SPEED_MODE;
  timer.duty_resolution = LEDC_TIMER_10_BIT;
  timer.timer_num = LEDC_TIMER_0;
  timer.freq_hz = 1000;
  timer.clk_cfg = LEDC_AUTO_CLK;
  ESP_ERROR_CHECK(ledc_timer_config(&timer));

  ledc_channel_config_t channel{};
  channel.gpio_num = board.pins.uartTx;
  channel.speed_mode = LEDC_LOW_SPEED_MODE;
  channel.channel = LEDC_CHANNEL_0;
  channel.intr_type = LEDC_INTR_DISABLE;
  channel.timer_sel = LEDC_TIMER_0;
  channel.duty = 512;  // 50% of the 10-bit period: 500 us HIGH, 500 us LOW.
  ESP_ERROR_CHECK(ledc_channel_config(&channel));

  SerialTransport serial;
  serial.begin();
  constexpr char ready[] = "# GPIO17 probe: 1000 Hz, 50% duty; actuator outputs disabled\n";
  for (;;) {
    serial.write(ready, sizeof ready - 1);
    serial.flush();
    vTaskDelay(pdMS_TO_TICKS(1000));
  }
}
